#!/usr/bin/env bash
# Repository validation for agent-workflows.
#
# Claude runs this script before reporting success, and the agent workflows
# run it again as a separate step after every implementation or remediation
# pass. Keep it equivalent to your CI checks. Exit non-zero on failure.
#
# Generated by `agent-workflows install`; edit freely (it is never overwritten).
set -euo pipefail

# Type-check .astro files (added by hand). `astro check` exits 0 WITHOUT checking
# anything when @astrojs/check or typescript is not installed, and it never
# installs them in CI, so refuse to continue without them. Prerequisite:
#   npm install --save-dev @astrojs/check typescript@^6
# (astro check does not support TypeScript 7.)
for pkg in @astrojs/check typescript; do
  if [ ! -f "node_modules/$pkg/package.json" ]; then
    echo "::error::astro check needs the $pkg devDependency: npm install --save-dev @astrojs/check typescript@^6"
    exit 1
  fi
done
npx astro check

npm run build
